-- Synthetic trigger-component dependencies only; no runtime authority claim.
create table public.paid_watch_party_offers(
  "created_at" timestamp with time zone,
  "creator_id" uuid,
  "currency" text,
  "description" text,
  "ends_at" timestamp with time zone,
  "host_id" uuid,
  "id" uuid default gen_random_uuid(),
  "metadata" jsonb,
  "party_id" text,
  "price_cents" integer,
  "provider" text,
  "provider_product_id" text,
  "provider_product_key" text,
  "seat_limit" integer,
  "seats_sold" integer,
  "starts_at" timestamp with time zone,
  "status" text,
  "title" text,
  "title_id" text,
  "updated_at" timestamp with time zone,
  "video_id" uuid
);
create table public.provider_events(
  "app_user_id" text,
  "created_at" timestamp with time zone,
  "environment" text,
  "event_type" text,
  "id" uuid default gen_random_uuid(),
  "idempotency_key" text,
  "metadata" jsonb,
  "occurred_at" timestamp with time zone,
  "product_id" uuid,
  "product_key" text,
  "provider" text,
  "provider_event_id" text,
  "raw_payload_hash" text,
  "status" text,
  "user_id" uuid
);
create table public.money_access_ledger_events(
  "amount_minor" integer,
  "created_at" timestamp with time zone,
  "creator_id" uuid,
  "currency" text,
  "environment" text,
  "event_type" text,
  "id" uuid default gen_random_uuid(),
  "metadata" jsonb,
  "payable_state" text,
  "platform_id" uuid,
  "product_id" uuid,
  "provider_event_id" uuid,
  "source_id" uuid,
  "source_type" text,
  "status" text,
  "user_id" uuid
);
create table public.creator_room_ticket_transactions(
  "amount_cents" integer,
  "buyer_id" uuid,
  "created_at" timestamp with time zone,
  "creator_id" uuid,
  "creator_net_cents" integer,
  "currency" text,
  "host_id" uuid,
  "id" uuid default gen_random_uuid(),
  "ledger_event_id" uuid,
  "metadata" jsonb,
  "offer_id" uuid,
  "paid_at" timestamp with time zone,
  "party_id" text,
  "payout_status" text,
  "platform_fee_cents" integer,
  "provider" text,
  "provider_event_id" uuid,
  "provider_fee_cents" integer,
  "provider_product_id" text,
  "provider_transaction_id" text,
  "refunded_at" timestamp with time zone,
  "status" text
);
create table public.paid_watch_party_tickets(
  "access_grant_id" uuid,
  "buyer_id" uuid,
  "created_at" timestamp with time zone,
  "creator_id" uuid,
  "expires_at" timestamp with time zone,
  "host_id" uuid,
  "id" uuid default gen_random_uuid(),
  "metadata" jsonb,
  "offer_id" uuid,
  "party_id" text,
  "provider" text,
  "provider_transaction_id" text,
  "refunded_at" timestamp with time zone,
  "revoked_at" timestamp with time zone,
  "source_transaction_id" uuid,
  "status" text,
  "used_at" timestamp with time zone
);
create table public.access_grants(
  "audit_id" uuid,
  "created_at" timestamp with time zone,
  "environment" text,
  "expires_at" timestamp with time zone,
  "grant_type" text,
  "id" uuid default gen_random_uuid(),
  "metadata" jsonb,
  "product_id" uuid,
  "provider" text,
  "provider_event_id" uuid,
  "refunded_at" timestamp with time zone,
  "revoke_reason" text,
  "revoked_at" timestamp with time zone,
  "source_id" uuid,
  "source_type" text,
  "starts_at" timestamp with time zone,
  "status" text,
  "updated_at" timestamp with time zone,
  "user_id" uuid
);
create table public.room_ticket_events(
  "actor_id" uuid,
  "created_at" timestamp with time zone,
  "event_type" text,
  "id" uuid default gen_random_uuid(),
  "metadata" jsonb,
  "offer_id" uuid,
  "ticket_id" uuid,
  "transaction_id" uuid
);
create unique index on public.creator_room_ticket_transactions(provider_event_id) where provider_event_id is not null;
create unique index on public.paid_watch_party_tickets(offer_id,buyer_id) where status='active';
